head.script:
scwin.screenId = "jldfil55340";

///////// 1. 변수 및 선언 영역 /////////




///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "isuSnm", fn: function () { return String(dlt_newListStkcertIsuCd.getCellData(0, "isuSnm")); } },
        { childId: "isuEngNm", fn: function () { return String(dlt_newListStkcertIsuCd.getCellData(0, "isuEngNm")); } },
        { childId: "isuEngSnm", fn: function () { return String(dlt_newListStkcertIsuCd.getCellData(0, "isuEngSnm")); } },
        { childId: "isuEngSymbl", fn: function () { return String(dlt_newListStkcertIsuCd.getCellData(0, "isuEngSymbl")); } },
        { childId: "isuRnd", fn: function () { return String(dlt_newListStkcertIsuCd.getCellData(0, "isuRnd")); } },
        { childId: "isuDd", fn: function () { return String(dlt_newListStkcertIsuCd.getCellData(0, "isuDd")); } },
        { childId: "secugrpId", fn: function () { return String(dlt_newListStkcertIsuCd.getCellData(0, "secugrpId")); } },
        { childId: "currIsoCd", fn: function () { return String(dlt_newListStkcertIsuCd.getCellData(0, "currIsoCd")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jldfil55340: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil55340.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_cancel_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_cancel_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_cancel_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.cancel()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55340.btn_cancel_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.returnIsuInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param tr
 * @returns
 * @hidden N
*/
scwin.returnIsuInfo = function (tr) {
    /* sdd-asis-lifecycle:begin returnIsuInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const opener = ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {});
    const index = tr.rowIndex - 1;
    const isuCdTd = "isuCd" + index;
    const isuSrtCdTd = "isuSrtCd" + index;
    const isuNmTd = "isuNm" + index;
    const isuSnmTd = "isuSnm" + index;
    const isuEngNmTd = "isuEngNm" + index;
    const isuEngSnmTd = "isuEngSnm" + index;
    const isuEngSymblTd = "isuEngSymbl" + index;
    const isuRndTd = "isuRnd" + index;
    const isuDdTd = "isuDd" + index;
    const secugrpId = "secugrpId" + index;
    const currIsoCd = "currIsoCd" + index;
    opener.isuCd = $c.util.getComponent(isuCdTd).getValue();
    opener.isuSrtCd = $c.util.getComponent(isuSrtCdTd).getValue();
    opener.isuNm = $c.util.getComponent(isuNmTd).getValue();
    opener.isuSnm = $c.util.getComponent(isuSnmTd).getValue();
    opener.isuEngNm = $c.util.getComponent(isuEngNmTd).getValue();
    opener.isuEngSnm = $c.util.getComponent(isuEngSnmTd).getValue();
    opener.isuEngSymbl = $c.util.getComponent(isuEngSymblTd).getValue();
    opener.isuRnd = $c.util.getComponent(isuRndTd).getValue();
    opener.isuDd = $c.util.getComponent(isuDdTd).getValue();
    opener.secugrpId = $c.util.getComponent(secugrpId).getValue();
    opener.currIsoCd = $c.util.getComponent(currIsoCd).getValue();
    opener.calcelYn = 'N';
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.cancel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.cancel = function () {
    /* sdd-asis-lifecycle:begin fn_cancel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const opener = ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {});
    opener.calcelYn = 'Y';
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
